import { readFile } from "node:fs/promises";
import { match } from "arktype";

/**
 * Use ArkType's `match({ ... })({ ... })` pattern matching API to
 * discriminate between success/error/pending API response payloads and
 * format each shape into a human-readable string.
 */
const formatPayload = match(
    {
        "{ status: 'success', data: object }": ({ data }) =>
            `OK: ${JSON.stringify(data)}`,
        "{ status: 'error', code: number, reason: string }": ({
            code,
            reason,
        }) => `ERR ${code} ${reason}`,
        "{ status: 'pending' }": () => "PENDING",
        default: "assert",
    }
);

async function main(): Promise<void> {
    // Read the entire stdin payload, parse it as JSON, and dispatch it to
    // the ArkType matcher. Any thrown error (e.g. from an unmatched input)
    // will propagate out of main and produce a non-zero exit code.
    const raw = await readFile(0, "utf8");
    const input: unknown = JSON.parse(raw);
    const result = formatPayload(input);
    process.stdout.write(`${result}\n`);
}

main().catch((err: unknown) => {
    console.error(err);
    process.exit(1);
});

